{
  "name": "action_artifact_cache",
  "description": "Manages caching of build dependencies and node modules across workflow runs.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "path": {
        "type": "string",
        "description": "Directory path to cache"
      },
      "key": {
        "type": "string",
        "description": "Unique cache key for restoration"
      }
    },
    "required": ["path", "key"]
  }
}

{
  "name": "next_route_generator",
  "description": "Scaffolds new page and layout files following the App Router directory structure.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "routePath": {
        "type": "string",
        "description": "Target path relative to the app directory"
      },
      "includeLoading": {
        "type": "boolean",
        "description": "Whether to generate a loading.tsx file"
      }
    },
    "required": ["routePath"]
  }
}

{
  "name": "ci_test_matrix_generator",
  "description": "Generates dynamic test execution matrices based on changed files in the pull request.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "maxParallel": {
        "type": "integer",
        "description": "Maximum number of concurrent jobs"
      }
    },
    "required": []
  }
}

{
  "name": "api_endpoint_mock_server",
  "description": "Spins up a lightweight local mock server returning predefined JSON fixtures for API testing.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "port": {
        "type": "integer",
        "description": "Port number for the mock server"
      },
      "fixturesDir": {
        "type": "string",
        "description": "Path to json response files"
      }
    },
    "required": ["fixturesDir"]
